#!/usr/bin/env python3
"""
RTM → Downtime PDF Scraper  |  McCain Hastings Packing Room
Overlays data from the RTM .xlsb onto the H520 Downtime Log template PDF.

Lines: 1, 2, 3
Day shift:   04:00 – 16:00 NZT
Night shift: 16:00 – 04:00 NZT

If more than 14 downtime events exist for one order block, the script
prints front + back on a single sheet (duplex / 2-page PDF).
"""

import os, sys, re, io, glob
import datetime
from typing import Optional, List, Dict

