# ── Shift constants ───────────────────────────────────────────────────────────
# Times are stored in NZT in the RTM. We display them -2h (NZT → AEST).
# So displayed 04:00–16:00 = NZT 06:00–18:00.
# DATA_* = filter window (NZT fractions); PRINT_* = what goes on the PDF header.
DATA_DAY_START   = 6/24    # NZT 06:00  → displayed 04:00
DATA_DAY_END     = 18/24   # NZT 18:00  → displayed 16:00
DATA_NIGHT_START = 18/24   # NZT 18:00  → displayed 16:00
DATA_NIGHT_END   = 6/24    # NZT 06:00  → displayed 04:00 (next day)
EXCEL_EPOCH = datetime.datetime(1899, 12, 30)

