# Roll-change wording, split by machine so a generic event (which otherwise
# goes to Notes) still ticks the right Roll change column from the direct cause.
# Phrases naming the machine's own film/poly map straight to that machine; the
# generic "roll change" / "changed roll" are resolved by which machine the
# event is on (bosch vs tape).
_BOSCH_ROLL_PHRASES = ("end of poly roll", "poly roll out", "poly roll")
_TAPE_ROLL_PHRASES  = ("end of tape roll", "tape roll out",
                       "tape roll finished", "new tape roll")
_GENERIC_ROLL_PHRASES = ("roll change", "changed roll")

def equip_to_col(equipment: str, reason: str = "", code: str = "",
                 direct: str = "") -> str:
    # Include the direct cause so the operator's own wording is considered,
    # not just the equipment/reason fields.
    combined = (f"{equipment} {reason} {direct}").lower()

    is_bosch = "bosch" in combined
    is_tape  = "tape"  in combined

    # Machine-specific roll wording wins outright.
    if any(p in combined for p in _BOSCH_ROLL_PHRASES):
        return "bosch_roll"
    if any(p in combined for p in _TAPE_ROLL_PHRASES):
        return "tape_roll"
    # Generic "roll change" / "changed roll": route by which machine it's on.
    if any(p in combined for p in _GENERIC_ROLL_PHRASES):
        if is_tape:  return "tape_roll"
        if is_bosch: return "bosch_roll"

    for needle, col in EQUIP_MAP:
        if needle in combined:
            return col
    # No clear equipment match → no column is ticked. The event still appears
    # in Notes (time + write-up), but never gets a guessed "X". (Previously a
    # code containing the letters "san"/"chg"/"sup" anywhere — e.g. an
    # evacuation coded "EVACSAN" — was wrongly marked Changeover.)
    return "notes"

# ── helpers ───────────────────────────────────────────────────────────────────
def frac_hhmm(f) -> str:
    if f is None: return ""
    m = round(float(f) * 1440) % 1440
    return f"{m//60:02d}:{m%60:02d}"

def frac_hhmm_adj(f) -> str:
    """RTM times minus 2 hours for display (NZT → AEST offset)."""
    if f is None: return ""
    m = (round(float(f) * 1440) - 120) % 1440
    return f"{m//60:02d}:{m%60:02d}"

# Stop words stripped when summarising long direct-cause text
_STOP = frozenset({
    'the','a','an','is','are','was','were','be','been','being',
    'have','has','had','do','does','did','will','would','could',
    'should','may','might','shall','to','of','in','on','at','by',
    'for','with','from','up','down','out','into','about','when',
    'not','no','this','that','these','those','it','its',
    'and','or','but','so','also','just','very','quite','even',
    'going','coming','getting','causing','which','when','as',
})

def smart_truncate(text: str, max_chars: int = 50) -> str:
    """
    If text fits within max_chars return it unchanged (full context preserved).
    Otherwise strip stop-words first, then hard-truncate at a word boundary
    with an ellipsis — so the key nouns/actions always remain readable.
    """
    if not text or len(text) <= max_chars:
        return text
    # Remove stop words, keep everything else
    words = text.split()
    kept = [w for w in words
            if re.sub(r"[^a-z]", "", w.lower()) not in _STOP]
    compressed = " ".join(kept)
    if len(compressed) <= max_chars:
        return compressed
    # Still too long — truncate at last word boundary
    trunc = compressed[:max_chars]
    last_sp = trunc.rfind(" ")
    if last_sp > max_chars * 0.55:
        trunc = trunc[:last_sp]
    return trunc + "…"

def delta_mins(a, b) -> float:
    if a is None or b is None: return 0.0
    d = float(b) - float(a)
    if d < 0: d += 1.0
    return round(d * 1440, 1)

def excel_date(s) -> datetime.date:
    return (EXCEL_EPOCH + datetime.timedelta(days=float(s))).date()

def in_shift(f, shift: str) -> bool:
    if f is None: return False
    # Normalise to nearest minute then wrap into [0, 1).
    # The xlsb format stores hour-boundary fractions with small floating-point
    # drift (e.g. 18:00 NZT is stored as 0.749999999999995 instead of 0.75).
    # Without this normalisation the 18:00-19:00 slot passes the Day filter
    # and night-shift order blocks (Line 2 ord 3511184, Line 3 ord 3511150)
    # bleed into the Day output.
    f = (round(float(f) * 1440) % 1440) / 1440
    if shift == "Day":
        return DATA_DAY_START <= f < DATA_DAY_END
    # Night crosses midnight
    return f >= DATA_NIGHT_START or f < DATA_NIGHT_END

def extract_size(name: str) -> str:
    """Pull bag size from product name e.g. '500g', '1kg'."""
    if not name: return ""
    hits = re.findall(r'(\d+(?:\.\d+)?)\s*(g|kg|G|KG|gm)', name)
    for qty, unit in reversed(hits):
        if unit.lower() == "kg" and float(qty) >= 100: continue
        return f"{qty}{unit.lower()}"
    return ""

def load_xlsb(path: str) -> dict:
    data = {}
    with open_workbook(path) as wb:
        for name in wb.sheets:
            with wb.get_sheet(name) as sh:
                data[name] = [[c.v for c in row] for row in sh.rows()]
    return data

def product_name(pm_rows, code) -> str:
    if code is None: return ""
    try: fc = float(code)
    except: fc = code
    for r in pm_rows[1:]:
        if r and r[0] == fc:
            return str(r[1]).strip() if r[1] else ""
    return str(code)

# ── RTM extraction ────────────────────────────────────────────────────────────
LINE_SHEETS = {
    1: ("P1 - Performance Record", "P1 - Downtime"),
    2: ("P2 - Performance Record", "P2 - Downtime"),
    3: ("P3 - Performance Record", "P3 - Downtime"),
}

def extract_blocks(all_data: dict, line: int, shift: str) -> List[Dict]:
    """Return a list of order blocks, each with header info + event list."""
    pm   = all_data.get("Product Master", [])
    dp   = all_data.get("DataPack", [])
    dt   = all_data.get("DataDowntime", [])

    # date from sheet header
    date_val = None
    for sn in LINE_SHEETS.get(line, ()):
        for r in all_data.get(sn, [])[1:3]:
            for v in r:
                if isinstance(v, float) and v > 40000:
                    date_val = excel_date(v); break
            if date_val: break
        if date_val: break

    # hourly performance blocks
    hourly = []
    for r in dp[1:]:
        if not r or len(r) < 6: continue
        if r[0] != float(line): continue
        if not in_shift(r[1], shift): continue
        op = str(r[3]).strip() if r[3] else ""
        ord_ = str(int(r[4])) if r[4] and r[4] != "" else ""
        prod = str(int(r[5])) if r[5] and r[5] != "" else ""
        if ord_:
            hourly.append({"t": float(r[1]), "t2": float(r[2]),
                           "op": op, "ord": ord_, "prod": prod})

    if not hourly:
        return []

    # Group by PRODUCT # — record the exact hourly slots that belong to each block.
    # Using product# (not order#) ensures that night-shift runs which the RTM splits
    # across two order numbers at midnight are treated as a single block.  A gap
    # (blank hour with no order) still starts a new block even for the same product,
    # so genuinely separate production runs are never silently merged.
    raw_blocks = []
    cur = None
    for h in sorted(hourly, key=lambda x: x["t"]):
        # New block when the PRODUCT changes OR there's a time gap (a blank hour
        # was skipped, so this slot doesn't start where the last one ended)
        gap = cur is not None and abs(h["t"] - cur["t_end"]) > 1e-6
        if cur is None or h["prod"] != cur["prod"] or gap:
            if cur: raw_blocks.append(cur)
            cur = dict(ord=h["ord"], prod=h["prod"], op=h["op"],
                       t_start=h["t"], t_end=h["t2"],
                       slots=[(h["t"], h["t2"])])
        else:
            # Keep the first order# seen for the header; extend time window
            cur["t_end"] = h["t2"]
            cur["slots"].append((h["t"], h["t2"]))
    if cur: raw_blocks.append(cur)

    # Printed start/stop come from the ACTUAL order window times.
    # Store RAW NZT here — frac_hhmm_adj() applies the single -2h offset at
    # display time, so do NOT subtract here (that caused a double -4h shift).
    for i, b in enumerate(raw_blocks):
        b["p_start"] = b["t_start"]                       # raw NZT first slot
        if len(raw_blocks) > 1 and i < len(raw_blocks) - 1:
            # Changeover: stop = when the next order's first slot begins
            b["p_stop"] = raw_blocks[i + 1]["t_start"]
        else:
            b["p_stop"] = b["t_end"]                       # raw NZT last slot end

    # enrich
    blocks = []
    for b in raw_blocks:
        pname = product_name(pm, b["prod"])
        blocks.append({
            "order": b["ord"], "prod_code": b["prod"],
            "prod_name": pname, "prod_size": extract_size(pname),
            "operator": b["op"], "date": date_val,
            "line": line, "shift": shift,
            "t_start": b["t_start"], "t_end": b["t_end"],
            "slots": b["slots"],          # exact order-present hour windows
            "p_start": b["p_start"], "p_stop": b["p_stop"],
            "events": [],
        })

    # Collect downtime events. Only keep an event if its stop time falls inside
    # one of the actual order-present hourly slots. Events during blank hours
    # (no order / no product running) are dropped entirely.
    events = []
    for r in dt[1:]:
        if not r or len(r) < 21: continue
        if r[0] != float(line): continue
        stopped = r[7]
        if not stopped or stopped == "": continue
        try:   sf = float(stopped)
        except: continue
        if not in_shift(sf, shift): continue
        try:   ef = float(r[8]) if r[8] and r[8] != "" else sf
        except: ef = sf
        dur   = delta_mins(sf, ef)
        equip = str(r[19]) if len(r) > 19 and r[19] else ""
        rsn   = str(r[20]) if len(r) > 20 and r[20] else ""
        code  = str(r[15]) if len(r) > 15 and r[15] else ""
        direct     = str(r[21]).strip() if len(r) > 21 and r[21] else ""
        corrective = str(r[23]).strip() if len(r) > 23 and r[23] else ""
        events.append({
            "sf": sf, "ef": ef,
            "stop": frac_hhmm_adj(sf), "start": frac_hhmm_adj(ef),
            "dur": dur, "equip": equip, "rsn": rsn, "code": code,
            "direct": direct, "corrective": corrective,
            "col": equip_to_col(equip, rsn, code, direct),
        })

    def in_slot(sf, slots):
        """True if stop-time sf lands within one of the order-present hour slots.

        Night-shift DataPack slots that cross midnight are stored with fracs > 1.0
        (e.g. 00:00-01:00 NZT = 1.0-1.0417).  DataDowntime stop-times for those
        same hours are stored as WRAPPED fracs < 1.0 (00:15 NZT = 0.010417).
        To match them correctly, if the slot list contains any frac > 1.0 we also
        try sf + 1.0 when sf is a small after-midnight fraction (< 0.5).
        """
        has_cross_midnight = any(lo > 1.0 or hi > 1.0 for lo, hi in slots)
        candidates = [sf]
        if has_cross_midnight and sf < 0.5:
            candidates.append(sf + 1.0)
        for try_sf in candidates:
            for lo, hi in slots:
                if lo <= hi:
                    if lo <= try_sf < hi: return True
                else:                   # slot crosses midnight (legacy fallback)
                    if try_sf >= lo or try_sf < hi: return True
        return False

    for ev in events:
        for blk in blocks:
            if in_slot(ev["sf"], blk["slots"]):
                blk["events"].append(ev)
                break
        # No match to any order-present slot → event discarded (no order running)

    # Filter: skip zero-duration events with no equipment (pure noise)
    for blk in blocks:
        blk["events"] = [e for e in blk["events"]
                         if e["dur"] > 0 or e["equip"]]

    return blocks

# ── ReportLab text baseline helper ────────────────────────────────────────────
def rl_baseline(pdf_top: float, pdf_bot: float, font_size: float = 7.5) -> float:
    """Return ReportLab y (bottom-origin) for text centred in a cell."""
    mid_pdf = (pdf_top + pdf_bot) / 2
    # cap-height ≈ 0.72 × font_size; baseline sits below visual mid
    cap_h = font_size * 0.72
    baseline_pdf = mid_pdf + cap_h / 2
    return PAGE_H - baseline_pdf

# Pre-compute data row baselines
ROW_BASELINE = [
    rl_baseline(DATA_LINE_PTS[i], DATA_LINE_PTS[i+1])
    for i in range(NUM_ROWS)
]
HDR_BASELINE = [
    rl_baseline(HDR_BORDERS[i], HDR_BORDERS[i+1])
    for i in range(len(HDR_BORDERS)-1)
]
FREQ_BASELINE  = rl_baseline(FREQ_TOP,  FREQ_BOT)
TOTAL_BASELINE = rl_baseline(TOTAL_TOP, TOTAL_BOT)

# ── Single page overlay ───────────────────────────────────────────────────────
def make_overlay(blk: dict, events_slice: List[Dict]) -> bytes:
    buf = io.BytesIO()
    c = rl_canvas.Canvas(buf, pagesize=(PAGE_W, PAGE_H))

    shift      = blk["shift"]
    start_str  = frac_hhmm_adj(blk["p_start"])
    stop_str   = frac_hhmm_adj(blk["p_stop"])
    date_str   = blk["date"].strftime("%d/%m/%Y") if blk.get("date") else ""

    def txt(x, y, text, font="Helvetica-Bold", size=7.5, anchor="left"):
        if not text: return
        c.setFont(font, size)
        if anchor == "left":     c.drawString(x, y, str(text))
        elif anchor == "center": c.drawCentredString(x, y, str(text))
        elif anchor == "right":  c.drawRightString(x, y, str(text))

    # ── Header row 1: Product Desc | Date | Size ─────────────────────────
    y1 = HDR_BASELINE[0]
    txt(82,  y1, blk["prod_name"].strip(), size=7.0)
    txt(DIV1+38, y1, date_str)
    txt(DIV2+30, y1, blk["prod_size"])

    # ── Header row 2: Product Code | Start Time | Operator ───────────────
    y2 = HDR_BASELINE[1]
    txt(63,  y2, blk["prod_code"])
    txt(DIV1+38, y2, start_str)
    op_label = smart_truncate(str(blk["operator"]), max_chars=22)
    txt(DIV2+42, y2, op_label, size=7.0)

    # ── Header row 3: Shift circle | Stop Time ───────────────────────────
    y3 = HDR_BASELINE[2]
    # MORN label centre x≈81, NIGHT centre x≈173  (both at pdf_y≈104)
    circ_pdf_y = (HDR_BORDERS[2] + HDR_BORDERS[3]) / 2   # centre of row 3
    circ_rl_y  = PAGE_H - circ_pdf_y
    c.setLineWidth(0.8)
    if shift == "Day":
        c.circle(81, circ_rl_y, 7.5, stroke=1, fill=0)
    else:
        c.circle(173, circ_rl_y, 7.5, stroke=1, fill=0)
    txt(DIV1+38, y3, stop_str)

    # ── Header row 4: Order | Line # | Machine ───────────────────────────
    y4 = HDR_BASELINE[3]
    txt(77,  y4, blk["order"])
    txt(DIV1+30, y4, str(blk["line"]))
    machine_name = "Filler" if blk["line"] == 1 else "Bosch"
    txt(DIV2+42, y4, machine_name, size=7.0)

    # ── Data rows ─────────────────────────────────────────────────────────
    col_count = {k: 0   for k, l, r in COL_EDGES if k not in ("time_stopped","time_started","notes")}
    col_mins  = {k: 0.0 for k, l, r in COL_EDGES if k not in ("time_stopped","time_started","notes")}

    # Accumulator for events that don't match any category column (col == "notes").
    # Their downtime minutes are rolled into the last column ("changeover") total.
    notes_mins = 0.0

    for i, ev in enumerate(events_slice[:NUM_ROWS]):
        by = ROW_BASELINE[i]

        # Time stopped always shown; Time Started only when duration > 0
        # time_stopped cx=28.5pt; time_started cx shifted to 66pt (visual centre)
        txt(COL["time_stopped"]["cx"], by, ev["stop"], anchor="center", size=7.0)
        if ev["dur"] > 0:
            txt(COL["time_started"]["cx"], by, ev["start"], anchor="center", size=7.0)

        col_key = ev["col"]

        # ── Notes column: 3 lines within ~21pt row ────────────────────────
        # notes cell measured from template: l≈623.9, r≈823.3 → ~199pt wide.
        # Inset text 3pt from the left border; leave a small right margin.
        notes_x = COL["notes"]["l"] + 3      # start just inside the cell border
        notes_w = COL["notes"]["r"] - COL["notes"]["l"] - 5   # usable width, ~194pt
        # At ~3.3pt per char for 6pt font → ~61 chars per line
        max_chars_sm = int(notes_w / 3.3)
        max_chars_xs = int(notes_w / 3.3)

        equip_str = ev["equip"] or ""
        direct_str = ev["direct"] or ""
        corrective_str = ev.get("corrective") or ""

        # How many non-empty lines determine vertical centering offsets
        lines_present = sum(bool(s) for s in [equip_str, direct_str, corrective_str])

        if lines_present == 1:
            offsets = [0, 0, 0]
        elif lines_present == 2:
            offsets = [4, -4, -4]
        else:
            offsets = [7, 0, -7]

        line_idx = 0
        if equip_str:
            equip_str = smart_truncate(equip_str, max_chars_sm)
            txt(notes_x, by + offsets[line_idx], equip_str,
                font="Helvetica-Bold", size=6.5)
            line_idx += 1

        if direct_str:
            direct_str = smart_truncate(direct_str, max_chars_sm)
            txt(notes_x, by + offsets[line_idx], direct_str,
                font="Helvetica", size=6.0)
            line_idx += 1

        if corrective_str:
            corrective_str = smart_truncate(corrective_str, max_chars_xs)
            txt(notes_x, by + offsets[line_idx], corrective_str,
                font="Helvetica-Oblique", size=6.0)

        if col_key == "notes":
            notes_mins += ev["dur"]   # roll unmatched event minutes into last column
        else:
            # Tick mark centred in category column
            txt(COL[col_key]["cx"], by, "X", anchor="center", size=8.0)
            col_count[col_key] += 1
            # Accumulate actual downtime minutes from time_stopped → time_started
            col_mins[col_key] += ev["dur"]

    # ── Summary rows ──────────────────────────────────────────────────────
    for col_key, count in col_count.items():
        if count:
            cx = COL[col_key]["cx"]
            txt(cx, FREQ_BASELINE, str(count), anchor="center", size=6.5)

    # Total minutes down per column (from time_stopped to time_started).
    for col_key, mins in col_mins.items():
        if mins > 0:
            cx = COL[col_key]["cx"]
            # Display as integer minutes if whole number, else 1 decimal place
            label = str(int(mins)) if mins == int(mins) else f"{mins:.1f}"
            txt(cx, TOTAL_BASELINE, label, anchor="center", size=6.5)

    # Total minutes down for unmatched (notes-only) events → wide Notes cell.
    if notes_mins > 0:
        label = str(int(notes_mins)) if notes_mins == int(notes_mins) else f"{notes_mins:.1f}"
        notes_cx = COL["notes"]["l"] + 3   # left-aligned inside the wide cell
        txt(notes_cx, TOTAL_BASELINE, label, anchor="left", size=6.5)

    c.save()
    buf.seek(0)
    return buf.read()

def stamp(template_path: str, overlay_bytes: bytes, writer: PdfWriter):
    """Merge one overlay onto template page and add to writer."""
    tpl_page = PdfReader(template_path).pages[0]
    ovl_page = PdfReader(io.BytesIO(overlay_bytes)).pages[0]
    tpl_page.merge_page(ovl_page)
    writer.add_page(tpl_page)

# ── CLI helpers ───────────────────────────────────────────────────────────────
def ask(msg, default=""):
    try:   v = input(msg).strip()
    except EOFError: v = ""
    return v or default

def pick(msg, opts, default=None):
    print(msg)
    for i, o in enumerate(opts, 1): print(f"  {i}. {o}")
    d = str(opts.index(default)+1) if default in opts else "1"
    while True:
        raw = ask(f"  Choice [1-{len(opts)}, Enter={d}]: ", d)
        try:
            idx = int(raw)-1
            if 0 <= idx < len(opts): return opts[idx]
        except ValueError: pass
        print("  Invalid.")

# ── main ──────────────────────────────────────────────────────────────────────
def main():
    print("""
                                                                              
       db                                          88888888ba,  888888888888  
      d88b                      ,d                 88      `"8b      88       
     d8'`8b                     88                 88        `8b     88       
    d8'  `8b     88       88  MM88MMM  ,adPPYba,   88         88     88       
   d8YaaaaY8b    88       88    88    a8"     "8a  88         88     88       
  d8"      '8b   88       88    88    8b       d8  88         8P     88       
 d8'        `8b  "8a,   ,a88    88,   "8a,   ,a8"  88      .a8P      88       
d8'          `8b  `"YbbdP'Y8    "Y888  `"YbbdP"'   88888888Y"'       88       
                                                                              
""")

    # Locate the folder where the script / exe lives — works on any machine.
    # When frozen by PyInstaller, sys.executable is the .exe itself; __file__
    # points into the temp extraction dir and is useless for finding data files.
    if getattr(sys, "frozen", False):
        # Running as a PyInstaller .exe — use the folder containing the .exe
        _HERE = os.path.dirname(os.path.abspath(sys.executable))
    else:
        try:
            _HERE = os.path.dirname(os.path.abspath(__file__))
        except NameError:
            _HERE = os.getcwd()

    _HANDWRITING_AVAILABLE = False  # handwriting font disabled

    # Auto-detect the RTM (.xlsb) — pick the first one found in the folder
    _xlsb = glob.glob(os.path.join(_HERE, "*.xlsb"))
    DEF_RTM = _xlsb[0] if _xlsb else os.path.join(_HERE, "RTM - Hastings Main.xlsb")

    # Auto-detect the PDF template — pick the first .pdf found in the folder
    _pdf = glob.glob(os.path.join(_HERE, "*.pdf"))
    DEF_TPL = _pdf[0] if _pdf else os.path.join(_HERE, "H520 Downtime Log - Packing.pdf")

    # Results always go into a "results" subfolder next to the script
    DEF_OUT = os.path.join(_HERE, "results")

    rtm = DEF_RTM
    tpl = DEF_TPL
    print(f"  RTM : {os.path.basename(rtm)}")
    print(f"  TPL : {os.path.basename(tpl)}")

    if not os.path.isfile(rtm):
        sys.exit(f"\n  ❌  RTM not found: {rtm}"
                 f"\n      Put the .xlsb file in the same folder as this script.")
    if not os.path.isfile(tpl):
        sys.exit(f"\n  ❌  Template not found: {tpl}"
                 f"\n      Put the Downtime Log PDF in the same folder as this script.")

    line  = int(pick("\nLine:", ["1","2","3"], "1"))
    shift = pick("\nShift:", ["Day (04:00–16:00)","Night (16:00–04:00)"],
                 "Day (04:00–16:00)")
    shift = "Day" if shift.startswith("Day") else "Night"

    print("\n  Loading RTM …", end=" ", flush=True)
    all_data = load_xlsb(rtm)
    print(f"{len(all_data)} sheets.")

    print(f"  Extracting Line {line} | {shift} shift …")
    blocks = extract_blocks(all_data, line, shift)

    if not blocks:
        print("  No data found.")
        sys.exit(0)

    print(f"\n  {len(blocks)} order block(s):")
    for b in blocks:
        ps = frac_hhmm_adj(b["p_start"]); pe = frac_hhmm_adj(b["p_stop"])
        print(f"    Ord {b['order']}  {b['prod_name'][:38]}  "
              f"({ps}–{pe})  {len(b['events'])} events")

    out_dir = ask(f"\nOutput dir [{DEF_OUT}]: ", DEF_OUT)
    # If user typed just a folder name (no path), place it next to the script
    if not os.path.dirname(out_dir):
        out_dir = os.path.join(_HERE, out_dir)
    try:
        os.makedirs(out_dir, exist_ok=True)
    except Exception as e:
        sys.exit(f"  ❌  Cannot create output folder '{out_dir}': {e}")

    for blk in blocks:
        evs   = blk["events"]
        total = len(evs)
        date_s = blk["date"].strftime("%Y%m%d") if blk.get("date") else "unk"
        sc     = "D" if shift == "Day" else "N"
        fname  = f"Downtime_L{line}_{sc}_{date_s}_Ord{blk['order']}.pdf"
        out    = os.path.join(out_dir, fname)

        writer = PdfWriter()

        # Split events into chunks of NUM_ROWS; one template page per chunk.
        # This prints front + back (and beyond if ever needed) with no event
        # ever dropped or scrambled.
        if total == 0:
            chunks = [[]]                       # still emit a blank-grid sheet
        else:
            chunks = [evs[i:i + NUM_ROWS]
                      for i in range(0, total, NUM_ROWS)]

        for chunk in chunks:
            ovl = make_overlay(blk, chunk)
            stamp(tpl, ovl, writer)
        pages = len(chunks)

        with open(out, "wb") as f:
            writer.write(f)

        abs_out = os.path.abspath(out)
        print(f"\n  ✅  {fname}  ({pages} page{'s' if pages>1 else ''}, {total} events)")
        print(f"      Saved to: {abs_out}")
        for ev in evs:
            mark = ev["col"] if ev["col"] != "notes" else "—notes—"
            print(f"      {ev['stop']}–{ev['start']}  {ev['dur']:5.1f}m  "
                  f"{ev['equip']:<24} → {mark}")

    print("\n  Done.")

if __name__ == "__main__":
    main()
